#!/bin/sh
# Codeceipt plugin launcher (generated by packages/agent-plugins; do not edit).
# Usage: codeceipt.sh hook <session-start|prompt|stop|session-end> <agent>
#        codeceipt.sh mcp <agent> [project folder]
# Runs the installed codeceipt with these fixed words. It never fails the agent's session: it always exits 0.
mode="$1"
case "$mode" in
  hook)
    event="$2"
    agent="$3"
    case "$event" in session-start | prompt | stop | session-end) ;; *) exit 0 ;; esac
    ;;
  mcp)
    event=""
    agent="$2"
    ;;
  *) exit 0 ;;
esac
case "$agent" in claude | cursor | codex | antigravity) ;; *) exit 0 ;; esac

# The session's folder: what the agent passed (MCP), else what it set in the environment. Only an absolute folder.
if [ "$mode" = mcp ]; then dir="$3"; else dir=""; fi
for d in "$dir" "$(printenv CLAUDE_PROJECT_DIR || true)" "$(printenv CURSOR_PROJECT_DIR || true)"; do
  case "$d" in
    /* | [A-Za-z]:[\\/]*) if [ -d "$d" ] && cd "$d" 2>/dev/null; then break; fi ;;
  esac
done

bin=""
for c in "$HOME/.local/bin/codeceipt" "$HOME/.local/bin/codeceipt.exe"; do
  if [ -f "$c" ] && [ -x "$c" ]; then
    bin="$c"
    break
  fi
done
if [ -z "$bin" ]; then
  found="$(PATH="$PATH:/usr/local/bin:/opt/homebrew/bin:$HOME/.npm-global/bin:$HOME/.volta/bin" command -v codeceipt 2>/dev/null || true)"
  case "$found" in /*) bin="$found" ;; esac
fi

if [ -z "$bin" ]; then
  if [ "$mode" = hook ] && [ "$event" = session-start ]; then
    case "$(uname -s 2>/dev/null)" in
      MINGW* | MSYS* | CYGWIN*) install='irm https://codeceipts.vercel.app/install.ps1 | iex' ;;
      *) install='curl -fsSL https://codeceipts.vercel.app/install.sh | sh' ;;
    esac
    printf 'Codeceipt is not installed on this computer, so this session gets no receipt. Install it with: %s\n' "$install" >&2
  fi
  if [ "$event" = prompt ] && [ "$agent" = cursor ]; then printf '{"continue":true}\n'; fi
  exit 0
fi

if [ "$mode" = mcp ]; then
  "$bin" mcp-proxy --linked-only
else
  "$bin" hook "$event" --agent "$agent" --plugin
fi
exit 0
